SELECT t1.id, t1.CODE, t1.type_code, t1.type_name, t1.workshop_code, t1.workshop_name, t1.line_code, t1.line_name, t1.shift_code, t1.shift_name, t1.LEVEL, t1.fault_code, t1.fault_name, t1.state, t1.create_by_name, t1.create_time, t1.ex_desc, t1.receive_time, t1.response_deadline, t1.handle_deadline, t1.escalation_count, t1.escalation_step, t1.next_escalation_time, t1.handler_name, t1.handler_code, t2.staff_name, t2.staff_code, t2.notice_type FROM mes_andon_notice t2 JOIN mes_andon_record t1 ON t1.CODE = t2.record_code AND t1.tenant_id = t2.tenant_id AND t1.factory_code = t2.factory_code AND t1.del_flag = '0' WHERE t2.del_flag = '0' AND t1.factory_code = #{factoryCode}
AND t1.type_name LIKE CONCAT('%',#{query.typeName},'%')
AND t1.code LIKE CONCAT('%',#{query.code},'%')
AND t1.level = #{query.level}
AND t2.staff_code = #{staffCode}
AND t1.state IN
#{state}
